import{_ as s,a0 as r,w as a,s as d,I as n,x as e,a1 as p,A as l,ao as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const b=JSON.parse('{"title":"如何在CentOS 7.x中安裝OpenERP（Odoo） | LCTT x X-CMD","titleTemplate":false,"description":"如何在CentOS 7.x中安裝OpenERP（Odoo） | LCTT (201506) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在CentOS 7.x中安裝OpenERP（Odoo） | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在CentOS 7.x中安裝OpenERP（Odoo） | LCTT (201506) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201506/20150506 How to Setup OpenERP (Odoo) on CentOS 7.x","title":"如何在CentOS 7.x中安裝OpenERP（Odoo）","tag":"201506","desc":""},"relativePath":"201506/20150506 How to Setup OpenERP (Odoo) on CentOS 7.x.md","filePath":"[post].md"}'),g={name:"201506/20150506 How to Setup OpenERP (Odoo) on CentOS 7.x.md"};function O(m,o,u,P,c,x){const t=r("Link");return a(),d("div",null,[o[15]||(o[15]=n("h1",{id:"如何在centos-7-x中安裝openerp-odoo",tabindex:"-1"},[e("如何在CentOS 7.x中安裝OpenERP（Odoo） "),n("a",{class:"header-anchor",href:"#如何在centos-7-x中安裝openerp-odoo","aria-label":"Permalink to “如何在CentOS 7.x中安裝OpenERP（Odoo）”"},"​")],-1)),o[16]||(o[16]=n("p",null,"各位好，這篇教程關於的是如何在CentOS 7中安裝Odoo（就是我們所知的OpenERP）。你是不是在考慮為你的業務安裝一個不錯的ERP（企業資源規劃）軟件？那麼OpenERP就是你尋找的最好的程序，因為它是一款為你的商務提供傑出特性的自由開源軟件。",-1)),n("p",null,[p(t,{href:"https://www.odoo.com/"},{default:l(()=>[...o[0]||(o[0]=[e("OpenERP",-1)])]),_:1}),o[1]||(o[1]=e("是一款自由開源的傳統的OpenERP（企業資源規劃），它包含了開源CRM、網站構建、電子商務、項目管理、計費賬務、POS、人力資源、市場、生產、採購管理以及其它模組用於提高效率及銷售。Odoo中的應用可以作為獨立程序使用，它們也可以無縫集成到一起，因此你可以在安裝幾個程序來得到一個全功能的開源ERP。",-1))]),o[17]||(o[17]=i(`<p>因此，下面是在你的CentOS上安裝OpenERP的步驟。</p><h3 id="_1-安裝-postgresql" tabindex="-1">1. 安裝 PostgreSQL <a class="header-anchor" href="#_1-安裝-postgresql" aria-label="Permalink to “1. 安裝 PostgreSQL”">​</a></h3><p>首先，首先我們需要更新CentOS 7的軟件包來確保是最新的包，補丁和安全更新。要更新我們的系統，我們要在shell下運行下面的命令。</p><pre><code># yum clean all
# yum update
</code></pre><p>現在我們要安裝PostgreSQL，因為OpenERP使用PostgreSQL作為它的資料庫。要安裝它，我們需要運行下面的命令。</p><pre><code># yum install postgresql postgresql-server postgresql-libs
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/03/installing-postgresql.png" alt="Installing postgresql"></p><p>安裝完成後，我們需要用下面的命令初始化資料庫。</p><pre><code># postgresql-setup initdb
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/03/intializating-postgresql.png" alt="Intializating postgresql"></p><p>我們接着設置PostgreSQL來使它每次開機啓動。</p><pre><code># systemctl enable postgresql
# systemctl start postgresql
</code></pre><p>因為我們還沒有為用户“postgresql”設置密碼，我們現在設置。</p><pre><code># su - postgres
$ psql
postgres=# \\password postgres
postgres=# \\q
# exit
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/03/setting-password-postgres.png" alt="setting password postgres"></p><h3 id="_2-設置odoo倉庫" tabindex="-1">2. 設置Odoo倉庫 <a class="header-anchor" href="#_2-設置odoo倉庫" aria-label="Permalink to “2. 設置Odoo倉庫”">​</a></h3><p>在初始化資料庫初始化完成後，我們要添加 EPEL（企業版Linux的額外包）到我們的CentOS中。Odoo（或者OpenERP）依賴的Python運行時環境以及其他包沒有包含在標準倉庫中。這樣我們要為企業版Linux添加額外的包倉庫支持來解決Odoo所需要的依賴。要安裝完成，我們需要運行下面的命令。</p><pre><code># yum install epel-release
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/03/installing-epel-release.png" alt="Installing EPEL Release"></p><p>現在，安裝EPEL後，我們現在使用yum-config-manager添加Odoo（OpenERP）的倉庫。</p><pre><code># yum install yum-utils

# yum-config-manager --add-repo=https://nightly.odoo.com/8.0/nightly/rpm/odoo.repo
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/03/added-odoo-repo.png" alt="Adding OpenERP (Odoo) Repo"></p><h3 id="_3-安裝odoo-8-openerp" tabindex="-1">3. 安裝Odoo 8 (OpenERP) <a class="header-anchor" href="#_3-安裝odoo-8-openerp" aria-label="Permalink to “3. 安裝Odoo 8 (OpenERP)”">​</a></h3><p>在CentOS 7中添加Odoo 8（OpenERP）的倉庫後。我們使用下面的命令來安裝Odoo 8(OpenERP)。</p><pre><code># yum install -y odoo
</code></pre><p>上面的命令會安裝odoo以及必須的依賴的包。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/03/installing-odoo.png" alt="Installing odoo or OpenERP"></p><p>現在我們使用下面的命令在每次啓動後啓動Odoo服務。</p><pre><code># systemctl enable odoo
# systemctl start odoo
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/03/starting-odoo.png" alt="Starting Odoo"></p><h3 id="_4-打開防火牆" tabindex="-1">4. 打開防火牆 <a class="header-anchor" href="#_4-打開防火牆" aria-label="Permalink to “4. 打開防火牆”">​</a></h3><p>因為Odoo使用8069端口，我們需要在防火牆中允許遠程訪問。我們使用下面的命令來在防火牆中允許8069端口訪問。</p><pre><code># firewall-cmd --zone=public --add-port=8069/tcp --permanent
# firewall-cmd --reload
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/03/allowing-firewall-port.png" alt="Allowing firewall Port"></p><p><strong>注意：默認情況下只有本地才允許連接資料庫。如果我們要允許PostgreSQL的遠程訪問，我們需要在pg_hba.conf添加下面圖片中一行</strong></p><pre><code># nano /var/lib/pgsql/data/pg_hba.conf
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/03/allowing-remote-access-pgsql.png" alt="Allowing Remote Access pgsql"></p><h3 id="_5-web接口" tabindex="-1">5. Web接口 <a class="header-anchor" href="#_5-web接口" aria-label="Permalink to “5. Web接口”">​</a></h3><p>我們已經在CentOS 7中安裝了最新的Odoo 8（OpenERP），我們可以在瀏覽器中輸入<code>http://ip-address:8069</code>來訪問Odoo。 接着，我們要做的第一件事就是創建一個新的資料庫和新的密碼。注意，主密碼默認是‘admin’。接着，我們可以在面板中輸入用户名和密碼。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/03/odoo-panel.png" alt="Odoo Panel"></p><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3><p>Odoo 8（OpenERP）是世界上最好的開源ERP程序。OpenERP是由許多模組組成的針對商務和公司的完整ERP程序，我們已經把它安裝好了。因此，如果你有任何問題、建議、反饋請在下面的評論欄寫下。謝謝你！享受OpenERP（Odoo 8）吧 ：-）</p><hr>`,43)),n("p",null,[o[3]||(o[3]=e("via: ",-1)),p(t,{href:"http://linoxide.com/linux-how-to/setup-openerp-odoo-centos-7/"},{default:l(()=>[...o[2]||(o[2]=[e("http://linoxide.com/linux-how-to/setup-openerp-odoo-centos-7/",-1)])]),_:1})]),n("p",null,[o[7]||(o[7]=e("作者：",-1)),p(t,{href:"http://linoxide.com/author/arunp/"},{default:l(()=>[...o[4]||(o[4]=[e("Arun Pyasi",-1)])]),_:1}),o[8]||(o[8]=e(" 譯者：",-1)),p(t,{href:"https://github.com/geekpi"},{default:l(()=>[...o[5]||(o[5]=[e("geekpi",-1)])]),_:1}),o[9]||(o[9]=e(" 校對：",-1)),p(t,{href:"https://github.com/wxy"},{default:l(()=>[...o[6]||(o[6]=[e("wxy",-1)])]),_:1})]),n("p",null,[o[12]||(o[12]=e("本文由 ",-1)),p(t,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...o[10]||(o[10]=[e("LCTT",-1)])]),_:1}),o[13]||(o[13]=e(" 原創翻譯，",-1)),p(t,{href:"https://linux.cn/"},{default:l(()=>[...o[11]||(o[11]=[e("Linux中國",-1)])]),_:1}),o[14]||(o[14]=e(" 榮譽推出",-1))])])}const f=s(g,[["render",O]]);export{b as __pageData,f as default};
